#!/bin/sh\n# nightly-docker-quote-mixer – whimsical quote dispenser\n\nquotes=\"The early bird gets the worm, but the second mouse gets the cheese.\nWhen life gives you lemons, make a lemonade stand on the moon.\nIn the apocalypse, a good joke is worth more than a bunker.\"\n\n# If an argument is supplied, treat it as a 0‑based line index for deterministic output (useful for tests)\nif [ -n \"$1\" ]; then\n  # sed is 1‑based, so add 1 to the index\n  idx=$(( $1 + 1 ))\n  echo \"$quotes\" | sed -n \"${idx}p\"\nelse\n  # Randomly select a line using shuf (installed via coreutils)\n  echo \"$quotes\" | shuf -n1\nfi\n
